create table if not exists public.marketing_settings(setting_key text primary key check(setting_key ~ '^[a-z0-9_]{2,80}$'),setting_value text not null default '',updated_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now());
alter table public.marketing_settings enable row level security; drop policy if exists "public reads marketing settings" on public.marketing_settings; drop policy if exists "admin manages marketing settings" on public.marketing_settings;
create policy "public reads marketing settings" on public.marketing_settings for select to anon,authenticated using(true); create policy "admin manages marketing settings" on public.marketing_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());
revoke all on public.marketing_settings from public; grant select on public.marketing_settings to anon,authenticated; grant insert,update,delete on public.marketing_settings to authenticated;
insert into public.marketing_settings(setting_key,setting_value) values('home_hero_title','Good things stay with you.'),('home_hero_subtitle','A thoughtful media space for Jewish teen girls. Real conversations, fresh perspectives, and inspiration for wherever life finds you.'),('mission_title','Less noise. More of what matters.'),('mission_body','Teens2Inspire makes meaningful media easier to find: relatable stories, thoughtful conversations, practical resources, Jewish life, and personal growth in one carefully curated space.'),('founder_bio','Goldie Fishbaum is the teen founder and host of Teens2Inspire. What began as a podcast has grown into a broader media platform for Jewish teen girls. Through honest interviews and thoughtful content, Goldie creates space for girls to hear real stories, explore questions, strengthen their values, and feel less alone as they navigate adolescence.'),('podcast_description','The Teens2Inspire Podcast features honest conversations, personal stories, and fresh perspectives from Jewish teen girls and the people who inspire them. Episodes explore friendship, peer pressure, tznius, tefilla, emunah, social media, school, and everyday growth.') on conflict(setting_key) do nothing;

create table if not exists public.partnerships(id uuid primary key default gen_random_uuid(),name text not null check(char_length(trim(name)) between 2 and 100),logo_url text not null,website_url text not null check(website_url ~ '^https://'),description text,display_order integer not null default 0 check(display_order>=0),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.partnerships enable row level security; drop policy if exists "public reads active partnerships" on public.partnerships; drop policy if exists "admin manages partnerships" on public.partnerships;
create policy "public reads active partnerships" on public.partnerships for select to anon,authenticated using(is_active=true or public.is_admin()); create policy "admin manages partnerships" on public.partnerships for all to authenticated using(public.is_admin()) with check(public.is_admin());
revoke all on public.partnerships from public; grant select on public.partnerships to anon,authenticated; grant insert,update,delete on public.partnerships to authenticated;
insert into public.partnerships(name,logo_url,website_url,description,display_order,is_active) select 'Mosaica Press','/partners/mosaica-press.svg','https://mosaicapress.com/','A publishing partner of Teens2Inspire.',1,true where not exists(select 1 from public.partnerships where lower(name)='mosaica press');
insert into public.partnerships(name,logo_url,website_url,description,display_order,is_active) select 'JCC of Marine Park','/partners/jcc-marine-park.svg','https://www.jccmp.org/','A community partner of Teens2Inspire.',2,true where not exists(select 1 from public.partnerships where lower(name)='jcc of marine park');

create table if not exists public.podcast_platforms(id uuid primary key default gen_random_uuid(),slug text not null unique check(slug ~ '^[a-z0-9-]{2,80}$'),name text not null check(char_length(trim(name)) between 2 and 80),logo_url text not null,website_url text not null check(website_url ~ '^https://'),display_order integer not null default 0 check(display_order>=0),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.podcast_platforms enable row level security; drop policy if exists "public reads active podcast platforms" on public.podcast_platforms; drop policy if exists "admin manages podcast platforms" on public.podcast_platforms;
create policy "public reads active podcast platforms" on public.podcast_platforms for select to anon,authenticated using(is_active=true or public.is_admin()); create policy "admin manages podcast platforms" on public.podcast_platforms for all to authenticated using(public.is_admin()) with check(public.is_admin());
revoke all on public.podcast_platforms from public; grant select on public.podcast_platforms to anon,authenticated; grant insert,update,delete on public.podcast_platforms to authenticated;
insert into public.podcast_platforms(slug,name,logo_url,website_url,display_order,is_active) values('spotify','Spotify','/podcast-platforms/spotify.svg','https://open.spotify.com/show/4rpRDVE1wGkP8trMxKfxZo',1,true),('apple-podcasts','Apple Podcasts','/podcast-platforms/apple-podcasts.svg','https://podcasts.apple.com/us/podcast/teens2inspire/id1853452190',2,true),('amazon-music','Amazon Music','/podcast-platforms/amazon-music.svg','https://music.amazon.com/podcasts/d9a85777-a125-49ab-a6d2-ef1ccb44a122/teens2inspire',3,true),('rss-com','RSS.com','/podcast-platforms/rss-com.svg','https://rss.com/podcasts/teens2inspire/',4,true),('24six','24Six','/podcast-platforms/24six.svg','https://24six.app/preview/podcast/collection/22024/teens2inspire',5,true) on conflict(slug) do nothing;
